	"charm.land/lipgloss/v2"
)

// rowStatus is the per-agent terminal state shown in the STATUS column.
type rowStatus int

const (
	rowStatusQueued rowStatus = iota
	rowStatusRunning
	rowStatusDone
	rowStatusFailed
)

// agentRow holds per-agent live state during the TUI run.
type agentRow struct {
	name         string
	status       rowStatus
	currentStart time.Time     // stamped on TurnStarted, zeroed on TurnFinished
	accumulated  time.Duration // sum of completed turn durations
	turnsTaken   int           // increments on TurnFinished (success or fail)
	maxTurns     int
	latestStance string // canonical: "approve" | "request-changes" | "abstain" | ""
	lastErr      error
}

// turnStartedMsg is sent when the loop begins an agent turn.
type turnStartedMsg struct {
	agent string
	turn  int
}

// turnFinishedMsg is sent when the loop finishes an agent turn (success or
// failure).
type turnFinishedMsg struct {
	agent    string
	turn     int
	stance   string
	duration time.Duration
	failed   bool
	err      error
}

// runFinishedMsg is sent once when the loop terminates.
type runFinishedMsg struct {
	outcome LoopOutcome
}

// tickMsg drives spinner + running-duration refresh between turn events.
type tickMsg time.Time

// investigateTUIModel is the Bubble Tea model for the investigate dashboard.
type investigateTUIModel struct {
	topic           string
	runID           string
	rows            []agentRow
	rowIdx          map[string]int
	quorum          int
	approvals       int
	completedRounds int
	maxRounds       int

	finished bool
	outcome  LoopOutcome

	cancel     context.CancelFunc
	cancelOnce *sync.Once

	spinner    spinner.Model
	termWidth  int
	termHeight int
}

// newInvestigateTUIModel builds an initial model pre-populated with one row
// per agent. cancel is invoked when the user presses Ctrl+C inside the TUI.
func newInvestigateTUIModel(topic, runID string, agents []string, maxTurns, quorum int, cancel context.CancelFunc) investigateTUIModel {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))

	rows := make([]agentRow, len(agents))
	rowIdx := make(map[string]int, len(agents))
	for i, name := range agents {
		rows[i] = agentRow{
			name:     name,
			status:   rowStatusQueued,
			maxTurns: maxTurns,
		}
		rowIdx[name] = i
	}
	return investigateTUIModel{
		topic:      topic,
		runID:      runID,
		rows:       rows,
		rowIdx:     rowIdx,
		quorum:     quorum,
		maxRounds:  maxTurns,
		cancel:     cancel,
		cancelOnce: &sync.Once{},
		spinner:    sp,
		termWidth:  80,
		termHeight: 24,
	}
}

func tickCmd() tea.Cmd {
	return tea.Tick(100*time.Millisecond, func(t time.Time) tea.Msg {
		return tickMsg(t)
	})
}

// Init kicks off the spinner and the refresh tick.
func (m investigateTUIModel) Init() tea.Cmd {
	return tea.Batch(m.spinner.Tick, tickCmd())
}

// Update handles all incoming messages.
func (m investigateTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case turnStartedMsg:
		return m.handleTurnStarted(msg), nil

	case turnFinishedMsg:
		return m.handleTurnFinished(msg), nil

	case runFinishedMsg:
		m.finished = true
		m.outcome = msg.outcome
		for i := range m.rows {
			if m.rows[i].status != rowStatusFailed {
				m.rows[i].status = rowStatusDone
			}
			if !m.rows[i].currentStart.IsZero() {
				m.rows[i].accumulated += time.Since(m.rows[i].currentStart)
				m.rows[i].currentStart = time.Time{}
			}
		}
		return m, nil

	case tickMsg:
		var spinCmd tea.Cmd
		m.spinner, spinCmd = m.spinner.Update(msg)
		return m, tea.Batch(spinCmd, tickCmd())

	case spinner.TickMsg:
		var spinCmd tea.Cmd
		m.spinner, spinCmd = m.spinner.Update(msg)
		return m, spinCmd

	case tea.WindowSizeMsg:
		m.termWidth = msg.Width
		m.termHeight = msg.Height
		return m, nil

	case tea.KeyPressMsg:
		return m.handleKey(msg)
	}
	return m, nil
}

// handleTurnStarted marks the named agent as running and stamps the start
// time. Unknown agents are ignored (defensive — should not happen given the
// rowIdx pre-population, but we'd rather drop a message than panic).
func (m investigateTUIModel) handleTurnStarted(msg turnStartedMsg) investigateTUIModel {
	idx, ok := m.rowIdx[msg.agent]
	if !ok {
		return m
	}
	row := &m.rows[idx]
	row.status = rowStatusRunning
	row.currentStart = time.Now()
	return m
}

// handleTurnFinished folds the just-completed turn into the row's
// accumulated state and updates the round counters.
func (m investigateTUIModel) handleTurnFinished(msg turnFinishedMsg) investigateTUIModel {
	idx, ok := m.rowIdx[msg.agent]
	if !ok {
		return m
	}
	row := &m.rows[idx]

	row.accumulated += msg.duration
	row.currentStart = time.Time{}
	row.turnsTaken++
	if msg.stance != "" && msg.stance != stanceUnknown {
		row.latestStance = msg.stance
	}
	if msg.failed {
		row.lastErr = msg.err
		if row.turnsTaken >= row.maxTurns {
			row.status = rowStatusFailed
		} else {
			row.status = rowStatusQueued
		}
	} else {
		row.status = rowStatusQueued
	}

	// Recompute round + approval counters from the full row set so we are
	// resilient to out-of-order messages and replays.
	totalTurns := 0
	approvals := 0
	for _, r := range m.rows {
		totalTurns += r.turnsTaken
		if r.latestStance == stanceApprove {
			approvals++
		}
	}
	if n := len(m.rows); n > 0 {
		m.completedRounds = totalTurns / n
	}
	m.approvals = approvals
	return m
}

// handleKey processes keyboard input.
func (m investigateTUIModel) handleKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	if m.finished {
		// Any key after finished dismisses.
		return m, tea.Quit
	}
	if msg.Code == 'c' && msg.Mod == tea.ModCtrl {
		m.cancelOnce.Do(m.cancel)
		return m, tea.Quit
	}
	return m, nil
}

// View renders the current frame.
func (m investigateTUIModel) View() tea.View {
	return tea.NewView(m.dashboardView())
}

// dashboardWidth returns the effective rendering width (defaulted when the
// terminal hasn't reported a size yet).
func (m investigateTUIModel) dashboardWidth() int {
	if m.termWidth <= 0 {
		return 80
	}
	return m.termWidth
}

// dashboardView renders the top banner, the table, and the footer hint.
func (m investigateTUIModel) dashboardView() string {
	var b strings.Builder

	m.writeLine(&b, m.titleLine())
	m.writeLine(&b, m.progressLine())
	b.WriteString("\n")
	m.writeLine(&b, m.headerLine())
	for _, row := range m.rows {
		m.writeLine(&b, m.renderRow(row))
	}
	b.WriteString("\n")
	if m.finished {
		m.writeLine(&b, m.outcomeLine())
		m.writeLine(&b, m.countsLine())
		m.writeLine(&b, "Press any key to exit.")
	} else {
		m.writeLine(&b, "Ctrl+C: cancel")
	}
	return b.String()
}

func (m investigateTUIModel) writeLine(b *strings.Builder, line string) {
	b.WriteString(truncateDisplayWidth(line, m.dashboardWidth()))
	b.WriteString("\n")
}

func (m investigateTUIModel) titleLine() string {
	if m.topic == "" {
		return fmt.Sprintf("Investigating (run %s)", m.runID)
	}
	return fmt.Sprintf("Investigating: %q (run %s)", sanitizeDisplayText(m.topic), m.runID)
}

func (m investigateTUIModel) progressLine() string {
	totalTurns := 0
	for _, r := range m.rows {
		totalTurns += r.turnsTaken
	}
	maxOverall := m.maxRounds * len(m.rows)
	round := m.completedRounds + 1
	if m.finished {
		round = max(m.completedRounds, 1)
	}
	return fmt.Sprintf("Round %d/%d · %d of %d turns · quorum %d/%d approvals",
		round, m.maxRounds, totalTurns, maxOverall, m.approvals, m.quorum)
}

func (m investigateTUIModel) headerLine() string {
	return m.renderTableLine("AGENT", "STATUS", "DURATION", "TURN", "APPROVED")
}

func (m investigateTUIModel) renderRow(row agentRow) string {
	statusStr := m.statusString(row)
	durStr := formatRowDuration(row)
	turnStr := fmt.Sprintf("%d/%d", row.turnsTaken, row.maxTurns)
	approvedStr := formatStance(row.latestStance)
	return m.renderTableLine(row.name, statusStr, durStr, turnStr, approvedStr)
}

// statusString renders STATUS for a row, including the live dot spinner for
// the currently-running agent.
func (m investigateTUIModel) statusString(row agentRow) string {
	switch row.status {
	case rowStatusRunning:
		return m.spinner.View() + " running"
	case rowStatusDone:
		return "✓ done"
	case rowStatusFailed:
		return "✗ failed"
	case rowStatusQueued:
		fallthrough
	default:
		return "queued"
	}
}

// renderTableLine emits one row of the table padded to fixed column widths.
// APPROVED takes whatever's left after the four fixed columns.
func (m investigateTUIModel) renderTableLine(agent, status, duration, turn, approved string) string {
	const (
		agentWidth    = 20
		statusWidth   = 12
		durationWidth = 9
		turnWidth     = 6
		separators    = 8 // four two-space separators between five columns
		minWidth      = agentWidth + statusWidth + durationWidth + turnWidth + separators
	)
	termWidth := m.dashboardWidth()
	approvedWidth := max(termWidth-minWidth, 0)
	line := fmt.Sprintf("%s  %s  %s  %s  %s",
		padDisplayWidth(agent, agentWidth),
		padDisplayWidth(status, statusWidth),
		padDisplayWidth(duration, durationWidth),
		padDisplayWidth(turn, turnWidth),
		truncateDisplayWidth(approved, approvedWidth))
	return truncateDisplayWidth(line, termWidth)
}

// outcomeLine renders the post-run "Outcome: <name>" summary.
func (m investigateTUIModel) outcomeLine() string {
	if m.outcome == "" {
		return ""
	}
	return fmt.Sprintf("Outcome: %s", m.outcome)
}

// countsLine renders the per-stance totals at the end of the run.
func (m investigateTUIModel) countsLine() string {
	app, chg, abs, unk := 0, 0, 0, 0
	for _, r := range m.rows {
		switch r.latestStance {
		case stanceApprove:
			app++
		case stanceRequestChanges:
			chg++
		case stanceAbstain:
			abs++
		default:
			unk++
		}
	}
	return fmt.Sprintf("%d agent(s) — %d approved, %d request-changes, %d abstain, %d unknown",
		len(m.rows), app, chg, abs, unk)
}

// formatRowDuration returns the display string for the DURATION column.
// While running it accumulates the in-flight elapsed time; otherwise it
// shows the total accumulated across completed turns. Empty when nothing
// has run yet.
func formatRowDuration(row agentRow) string {
	total := row.accumulated
	if !row.currentStart.IsZero() {
		total += time.Since(row.currentStart)
	}
	if total <= 0 {
		return ""
	}
	return formatDuration(total)
}

// formatDuration is a near-copy of review.formatDuration. Kept private so
// the investigate TUI does not pull in the review package.
func formatDuration(d time.Duration) string {
	if d < time.Second {
		return fmt.Sprintf("%dms", d.Milliseconds())
	}
	if d < time.Minute {
		return fmt.Sprintf("%.1fs", d.Seconds())
	}
	return fmt.Sprintf("%dm%ds", int(d.Minutes()), int(d.Seconds())%60)
}

// formatStance renders the APPROVED column from a canonical stance.
func formatStance(stance string) string {
	switch stance {
	case stanceApprove:
		return "✓ approve"
	case stanceRequestChanges:
		return "✗ changes"
	case stanceAbstain:
		return "— abstain"
	default:
		return ""
	}
}

// Package review — see env.go for package-level rationale.
//
// multipicker.go provides spawn-time agent multi-selection and per-run
// prompt collection for multi-agent review runs. When 2+ launchable agents
// are configured AND the user has not passed --agent, the dispatch logic
// in cmd.go calls PickAgents to let the user choose a subset and optionally
// add a one-off prompt without editing settings.
package review

import (
	"context"
	"errors"
	"fmt"
	"sort"

	"charm.land/huh/v2"
)

// PickedAgents is the result of PickAgents: the agents the user selected
// for this run, plus an optional per-run prompt to append to the composed
// review prompt for each agent.
type PickedAgents struct {
	// Names contains the agent registry keys selected by the user,
	// e.g. ["claude-code", "codex"]. Sorted alphabetically.
	Names []string

	// PerRun is optional textarea content; "" when the user skipped or cleared it.
	PerRun string
}

// ErrPickerCancelled is returned when the user aborts the multi-select.
var ErrPickerCancelled = errors.New("agent picker cancelled")

// ErrNoAgentsSelected is returned when the user unchecks all agents.
// Caller should surface a clear error rather than running with zero agents.
var ErrNoAgentsSelected = errors.New("no agents selected for review")

// PickAgents shows a multi-select form populated from eligible (the agents
// that are both configured AND have an AgentReviewer), pre-checks all of
// them, and returns the user's selection plus an optional per-run prompt.
//
// Returns ErrPickerCancelled if the user aborts. An empty selection (user
// unchecked all boxes) returns ErrNoAgentsSelected.
//
// Requires len(eligible) >= 2; returns an error if the caller passes fewer
// than 2 choices — this function is for multi-agent flows only.
func PickAgents(ctx context.Context, eligible []AgentChoice) (PickedAgents, error) {
	if len(eligible) < 2 {
		return PickedAgents{}, fmt.Errorf("PickAgents requires at least 2 eligible agents, got %d", len(eligible))
	}
	if ctx.Err() != nil {
		return PickedAgents{}, ErrPickerCancelled
	}

	// Sort alphabetically for stable display order regardless of how the
	// caller populated the slice.
	sorted := make([]AgentChoice, len(eligible))
	copy(sorted, eligible)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Name < sorted[j].Name })

	// Build options pre-selected (all agents checked by default — mirrors
	// PR #1018 behaviour so the user can just press Enter to run all).
	options := make([]huh.Option[string], 0, len(sorted))
	for _, c := range sorted {
		options = append(options, huh.NewOption(c.Label, c.Name).Selected(true))
	}

	var picked []string
	multiForm := newAccessibleForm(huh.NewGroup(
		buildAgentMultiSelect(options, &picked),
	))
	if err := multiForm.RunWithContext(ctx); err != nil {
		return PickedAgents{}, ErrPickerCancelled
	}

	if len(picked) == 0 {
		return PickedAgents{}, ErrNoAgentsSelected
	}

	// Sort the selection alphabetically so the caller receives a stable slice.
	sort.Strings(picked)

	// Per-run prompt: optional textarea presented after agent selection.
	var perRun string
	promptForm := newAccessibleForm(huh.NewGroup(
		huh.NewText().
			Title("Optional per-run prompt").
			Description("e.g. 'focus on auth' — appended to the review prompt for this run only. Leave blank to skip.").
			Value(&perRun),
	))
	if err := promptForm.RunWithContext(ctx); err != nil {
		// Cancellation on the prompt step (Ctrl+C) propagates as picker
		// cancelled — we don't want an empty prompt here; user can retry.
		return PickedAgents{}, ErrPickerCancelled
	}

	return PickedAgents{Names: picked, PerRun: perRun}, nil
}

func buildAgentMultiSelect(options []huh.Option[string], picked *[]string) *huh.MultiSelect[string] {
	return huh.NewMultiSelect[string]().
		Title("Which agents should run this review?").
		Options(options...).
		Height(len(options) + 1).
		Value(picked)
}

// Package review — see env.go for package-level rationale.
//
// tui_detail.go provides detailView, the pure-function renderer for the
// alt-screen drill-in view. It renders one agent's live event buffer with
// header/footer chrome and pads to exactly termHeight lines so every frame
// has the same line count (avoids ghost rows in the Bubble Tea alt-screen
// frame diff).
package review

import (
	"fmt"
	"strings"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// eventLine converts a single Event to a single display line for the detail
// view. The line is stripped of control sequences and truncated to maxWidth
// display cells.
func eventLine(ev reviewtypes.Event, maxWidth int) string {
	var raw string
	switch e := ev.(type) {
	case reviewtypes.Started:
		raw = "[started]"
	case reviewtypes.AssistantText:
		raw = e.Text
	case reviewtypes.ToolCall:
		raw = fmt.Sprintf("[tool: %s] %s", e.Name, e.Args)
	case reviewtypes.Tokens:
		raw = fmt.Sprintf("[tokens in=%d out=%d]", e.In, e.Out)
	case reviewtypes.Finished:
		if e.Success {
			raw = "[finished: success]"
		} else {
			raw = "[finished: failed]"
		}
	case reviewtypes.RunError:
		if e.Err != nil {
			raw = fmt.Sprintf("[error: %v]", e.Err)
		} else {
			raw = "[error]"
		}
	default:
		raw = "[unknown event]"
	}

	return truncateDisplayWidth(sanitizeDisplayText(raw), maxWidth)
}

// detailView renders the alt-screen drill-in for one agent. row is the agentRow
// being inspected. termWidth/termHeight come from WindowSizeMsg.
//
// Rendering:
//  1. Header line: "─── <name> (<n> events) ─────────────" (filled to termWidth)
//  2. Body: events from row.buffer scrolled to detailScroll, one line each,
//     sanitized and truncated to termWidth display cells.
//  3. Footer line: "←/→ switch agent · Esc back · ↑/↓ scroll"
//
// CRITICAL: the rendered string is padded to exactly termHeight lines so every
// frame has the same line count. Bubble Tea's alt-screen frame diff leaves ghost
// rows if the line count varies between frames.
func detailView(row agentRow, detailScroll, termWidth, termHeight int) string {
	if termWidth < 1 {
		termWidth = 80
	}
	if termHeight < 3 {
		termHeight = 3
	}

	// Reserve 1 line for header, 1 for footer; the body fills the rest.
	bodyHeight := termHeight - 2
	if bodyHeight < 0 {
		bodyHeight = 0
	}

	// 1. Header line.
	headerContent := fmt.Sprintf("─── %s (%d events) ", sanitizeDisplayText(row.name), len(row.buffer))
	header := padDisplayWidthWith(headerContent, termWidth, "─")

	// 2. Body lines.
	lines := buildBodyLines(row.buffer, detailScroll, bodyHeight, termWidth)

	// Pad body to exactly bodyHeight lines.
	for len(lines) < bodyHeight {
		lines = append(lines, strings.Repeat(" ", termWidth))
	}

	// 3. Footer line.
	footerText := "←/→ switch agent · Esc back · ↑/↓ scroll"
	footer := padDisplayWidth(footerText, termWidth)

	// Assemble: header + body + footer = termHeight lines total.
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("\n")
	for _, line := range lines {
		b.WriteString(line)
		b.WriteString("\n")
	}
	b.WriteString(footer)
	// No trailing newline after footer — the caller (View) adds its own.

	return b.String()
}

// buildBodyLines computes the visible body lines for the detail view.
// It takes the full event buffer, a scroll offset, the maximum number of lines
// to show, and the column width. Returns at most bodyHeight lines.
func buildBodyLines(buffer []reviewtypes.Event, scroll, bodyHeight, termWidth int) []string {
	if len(buffer) == 0 || bodyHeight <= 0 {
		return nil
	}

	// Clamp scroll to valid range.
	if scroll < 0 {
		scroll = 0
	}
	if scroll >= len(buffer) {
		scroll = len(buffer) - 1
	}

	// Determine window: scroll is the index of the LAST visible line so the
	// user sees the most-recent events when auto-scrolling. Work backwards.
	end := scroll + 1 // exclusive upper bound
	start := end - bodyHeight
	if start < 0 {
		start = 0
	}
	// Clamp end to buffer length.
	if end > len(buffer) {
		end = len(buffer)
		start = end - bodyHeight
		if start < 0 {
			start = 0
		}
	}

	lines := make([]string, 0, end-start)
	for i := start; i < end; i++ {
		lines = append(lines, eventLine(buffer[i], termWidth))
	}
	return lines
}

// Package investigate — see env.go for package-level rationale.
//
// progress.go defines ProgressSink, the consumer-side abstraction the loop
// uses to surface turn lifecycle events to whatever UI is rendering the run.
// Two implementations live in this package: textProgressSink (headless, used
// for non-TTY stdout) and tuiProgressSink (Bubble Tea dashboard, used for
// interactive runs). Tests inject their own fakes.
//
// The sink is the only seam between the loop and the UI; the loop never
// imports bubbletea or writes formatted lines directly. This mirrors the
// review package's Sink pattern.
package investigate

import (
	"fmt"
	"io"
	"sync"
	"time"
)

// ProgressSink consumes turn lifecycle events from RunInvestigateLoop. The
// loop invokes the methods from a single goroutine — implementations need
// not synchronize against themselves.
//
// Implementations MUST NOT block. The loop calls these synchronously around
// the per-turn agent spawn; a slow sink stalls the entire investigation.
type ProgressSink interface {
	// TurnStarted is called immediately before the agent process starts for
	// the given turn. perAgentTurn is the 1-indexed count of turns this
	// agent has taken (this one included); maxPerAgent is the configured
	// per-agent budget.
	TurnStarted(agent string, turn, perAgentTurn, maxPerAgent int)

	// TurnFinished is called once after the agent process exits AND the
	// timeline doc has been parsed for the freshly-added turn block. stance
	// is one of "approve", "request-changes", "abstain", "unknown". duration
	// is the wall-clock duration of the agent process. failed is true when
	// the turn was treated as a failure by the loop (spawn error, missing
	// heading, etc.); err is the underlying error or nil.
	TurnFinished(agent string, turn int, stance string, duration time.Duration, failed bool, err error)

	// RunFinished is called once when the loop terminates (any outcome).
	// The TUI uses this to flip rows to a terminal status and freeze the
	// dashboard; the text sink may print a final outcome line.
	RunFinished(outcome LoopOutcome)
}

// nullProgressSink is the zero-overhead default: every method is a no-op.
// Used when callers pass LoopDeps.Progress == nil (most tests).
type nullProgressSink struct{}

func (nullProgressSink) TurnStarted(string, int, int, int)                            {}
func (nullProgressSink) TurnFinished(string, int, string, time.Duration, bool, error) {}
func (nullProgressSink) RunFinished(LoopOutcome)                                      {}

// textProgressSink writes today's two-line shape to a plain io.Writer:
//
//	Turn N · <agent>
//	  Stance: <stance>
//
// Used when the terminal cannot render the Bubble Tea TUI (non-TTY stdout,
// CI, agent-host invocations). The mutex guards Writer access because while
// the loop is single-threaded, the sink is also invoked from RunFinished
// after the loop returns — a tiny gap, but cheap to lock.
type textProgressSink struct {
	mu sync.Mutex
	w  io.Writer
}

func newTextProgressSink(w io.Writer) *textProgressSink {
	return &textProgressSink{w: w}
}

func (s *textProgressSink) TurnStarted(agent string, turn, _, _ int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.w == nil {
		return
	}

	_, _ = fmt.Fprintf(s.w, "Turn %d · %s\n", turn, agent)
}

func (s *textProgressSink) TurnFinished(_ string, _ int, stance string, _ time.Duration, _ bool, _ error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.w == nil {
		return
	}

	_, _ = fmt.Fprintf(s.w, "  Stance: %s\n", stance)
}

func (s *textProgressSink) RunFinished(_ LoopOutcome) {
	// The text sink emits per-turn lines only; the post-run footer is the
	// caller's responsibility (writeInvestigateFooter in cmd.go). Nothing
	// to do here.
}

// Compile-time interface checks.
var (
	_ ProgressSink = nullProgressSink{}
	_ ProgressSink = (*textProgressSink)(nil)
)

// Package investigate — see env.go for package-level rationale.
//
// picker.go implements the first-run config picker for `entire
// investigate`. The picker shows a multi-select of agents that are both
// installed (hooks present) and launchable (a non-nil Spawner exists for
// them), then prompts for max-turns / quorum, and returns an
// InvestigateConfig the caller can persist.
package investigate

import (
	"context"
	"errors"
	"fmt"
